//! JOSE/COSE/JWT/CWT claims and headers registry.
//!
//! A [`Registry`] holds entries from the IANA CWT, COSE, JWT, and JOSE
//! registries, plus local additions for codepoints that IANA hasn't
//! registered yet (SD-CWT tags and simple values, token-relevant CBOR tags).
//! The bundled snapshot is generated by `tools/registry-gen` from the IANA
//! XML and embedded with `include_bytes!`. [`Registry::merge_iana`] merges a
//! refreshed fetch over it. The library performs no I/O: fetching and caching
//! are the caller's job.
//!
//! [`Registry::shared`] parses the bundled snapshot once and returns a
//! `&'static Registry`; [`Registry::bundled`] returns an owned copy to merge
//! into. [`Annotator`] maps keys and values to display names by context.
//!
//! ```
//! use tokenator_registry::{EntryKind, Registry};
//!
//! let reg = Registry::shared()?;
//! assert_eq!(reg.cose_header(4).unwrap().name, "kid");
//! assert_eq!(reg.by_name(EntryKind::CoseAlg, "ML-DSA-65").unwrap().label, (-49).into());
//! assert_eq!(reg.jwt_to_cwt("cnf"), Some(&8.into()));
//! # Ok::<(), tokenator_registry::RegistryError>(())
//! ```

mod annotate;
mod entry;
mod error;
mod parse;
mod registry;

pub use annotate::{Annotator, Context, Family};
pub use entry::{Entry, EntryKind, Label, RegistryId, Source, SpecRef};
pub use error::RegistryError;
pub use parse::{LocalAdditions, ParsedRegistry, parse_iana};
pub use registry::{Registry, RegistryStats, SnapshotInfo};
